package com.groupironmencompanion.scene;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * The worn-model table generated by {@code tools/geardump}, read from the jar.
 * <p>
 * The running client cannot say what an item looks like worn - {@code ItemComposition} has only
 * the flat inventory icon - so the model ids are extracted from the game cache at build time
 * and bundled. Same approach as the world map's area data, and for the same reason: the plugin
 * must never reach for the cache or the filesystem itself.
 * <p>
 * Because it is a snapshot, items added to the game after it was generated are simply absent.
 * That degrades to the member's own body showing through for that slot rather than to an
 * error, which is the right failure: a new cape going undrawn on a translucent figure is not
 * worth a broken model over. Regenerate after a game update to pick them up.
 */
@Slf4j
final class GearTable
{
	/** Must match {@code GearDump.FORMAT_VERSION}. */
	private static final int FORMAT_VERSION = 1;

	private static final String RESOURCE = "/com/groupironmencompanion/gear.dat";

	/**
	 * Sanity bounds on the record counts, so a truncated or wrong resource fails the load
	 * rather than trying to allocate from a length field that is really something else.
	 */
	private static final int MAX_ITEMS = 100_000;
	private static final int MAX_BODY_PARTS = 16;

	/** Item id to {@code {model0, model1, model2}}. */
	private final Map<Integer, int[]> worn;

	/** Default model per male body part: hair, jaw, torso, arms, hands, legs, feet. */
	private final int[] body;

	private GearTable(Map<Integer, int[]> worn, int[] body)
	{
		this.worn = worn;
		this.body = body;
	}

	/** Loads the bundled table, or null when it is missing or unreadable. */
	@Nullable
	static GearTable load()
	{
		try (InputStream resource = GearTable.class.getResourceAsStream(RESOURCE))
		{
			if (resource == null)
			{
				log.warn("Group Ironmen Companion: the worn-model table is missing from the jar");
				return null;
			}

			try (DataInputStream stream = new DataInputStream(resource))
			{
				int version = stream.readInt();
				if (version != FORMAT_VERSION)
				{
					log.warn("Group Ironmen Companion: worn-model table is version {}, expected {}",
						version, FORMAT_VERSION);
					return null;
				}

				int parts = stream.readInt();
				if (parts < 0 || parts > MAX_BODY_PARTS)
				{
					log.warn("Group Ironmen Companion: worn-model table declares {} body parts", parts);
					return null;
				}

				int[] body = new int[parts];
				for (int i = 0; i < parts; i++)
				{
					body[i] = stream.readInt();
				}

				int count = stream.readInt();
				if (count < 0 || count > MAX_ITEMS)
				{
					log.warn("Group Ironmen Companion: worn-model table declares {} items", count);
					return null;
				}

				Map<Integer, int[]> worn = new HashMap<>(count * 2);
				for (int i = 0; i < count; i++)
				{
					int id = stream.readInt();
					int model0 = stream.readInt();
					int model1 = stream.readInt();
					int model2 = stream.readInt();
					// The vertical offset is read to keep the record aligned. It positions a
					// mesh on the real player model; the figure here is assembled from whole
					// parts at the same origin, so nothing uses it yet.
					stream.readShort();
					worn.put(id, new int[]{model0, model1, model2});
				}

				log.debug("Loaded worn models for {} items", worn.size());
				return new GearTable(worn, body);
			}
		}
		catch (IOException e)
		{
			log.warn("Group Ironmen Companion: could not read the worn-model table", e);
			return null;
		}
	}

	/** The worn meshes for an item, or null when the table does not know it. */
	@Nullable
	int[] wornModels(int itemId)
	{
		return worn.get(itemId);
	}

	/** The default model for a male body part, or -1 when there is none. */
	int bodyModel(int part)
	{
		return part >= 0 && part < body.length ? body[part] : -1;
	}

	int itemCount()
	{
		return worn.size();
	}
}
